/* From Uiverse.io by gharsh11032000  - Tags: card, hover, hover effect, hoverme, cardhover , card hover */
.__UIV_SCOPE__ .card {
  width: 320px;
  height: 350px;
  padding: 20px;
  color: white;
  background: transparent;
  border: 2px solid #ff6b00;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transform-origin: center center;
  transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.__UIV_SCOPE__ .card .main-content {
  flex: 1;
}

.__UIV_SCOPE__ .header {
  margin-bottom: 24px;
}

.__UIV_SCOPE__ .card .heading {
  font-size: 32px;
  font-weight: 400;
  line-height: 1.2;
}

.__UIV_SCOPE__ .card .footer {
  font-weight: 400;
  margin-right: 4px;
}

.__UIV_SCOPE__ .card:hover {
  border-radius: 12px;
  background-color: #ff6b00;
  scale: 0.95;
  rotate: 8deg;
  box-shadow: 0px 3px 187.5px 7.5px rgba(255, 107, 0, 0.4);
}
